<script setup lang="ts">import { computed } from 'vue'; import { formatMoney } from '../../utils/formatters'; import type { ExpenseSummary } from '../../types'; const props = defineProps<{ summary: ExpenseSummary }>(); const cards = computed(() => [{ label: 'Total expenses', value: formatMoney(props.summary.total_amount) }, { label: 'Transactions', value: String(props.summary.transaction_count) }, ...(props.summary.average_amount ? [{ label: 'Average expense', value: formatMoney(props.summary.average_amount) }] : []), ...(props.summary.largest_amount ? [{ label: 'Largest expense', value: formatMoney(props.summary.largest_amount) }] : [])]);</script>
<template><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><article v-for="card in cards" :key="card.label" class="card"><p class="text-sm text-slate-500">{{ card.label }}</p><p class="mt-2 text-xl font-semibold tabular-nums">{{ card.value }}</p></article></div></template>
